local c=workspace.CurrentCamera.CFrame local r=RaycastParams.new() local h=workspace:Raycast(c.Position,c.LookVector*2000,r) if not h then warn("Vise le sol au centre de l'écran") return end local old=workspace:FindFirstChild("PointBalle") if old then old:Destroy() end local p=Instance.new("Part") p.Name="PointBalle" p.Anchored=true p.CanCollide=false p.CanQuery=false p.CanTouch=false p.Size=Vector3.new(2,2,2) p.Shape=Enum.PartType.Ball p.Color=Color3.fromRGB(255,60,60) p.Material=Enum.Material.Neon p.Position=h.Position+Vector3.new(0,1,0) p.Parent=workspace game:GetService("Selection"):Set({p}) print("PointBalle posé ! (invisible en jeu)")
